import type {Snapshot} from '../../src/core/model';
// Every identity, product, image and glyph in this fixture is original and fictional.
export const fontBase64='';
const component=`<template><section id="catalog"><span class="search-state">{{shouldUseNewSearchStrategy?'new-search':'classic-search'}}</span><span class="price-state">{{hasPrice?'priced':'missing-price'}}</span><span class="filter-state">{{filterCount}}</span><span class="sample-state">{{sampleCount}}</span><span class="cache-state">{{cachedMeta}}</span><div class="cards"><a v-for="item in products" :key="item.id" class="product-link" :href="$safeCleanLink(item.url_path)"><span class="custom-image -loading"><img class="-loading" v-lazyload :data-src="item.images.data[0].url" :alt="item.name"></span><b>{{item.name}}</b><span>{{item.prices.data.price_formated}}</span></a></div></section></template>
<script>import merchant from '@/mixins/merchant';import prices from '@/mixins/prices';import product from '@/mixins/product';import client from '@/modules/axios/api';import {getImageMeta} from '@/mixins/helpers';export default {name:'FixtureCatalog',mixins:[merchant,product,prices],props:['products'],data:()=>({filterCount:0,sampleCount:0,cachedMeta:''}),async mounted(){const filters=await client.get('/filters');this.filterCount=filters.data.data.attributes.length;const result=await client.get('/products?price_min=20&price_max=80');this.sampleCount=result.data.data.length;const src=this.products[0].images.data[0].url;getImageMeta(src,(w,h)=>{getImageMeta(src,(cw,ch)=>{this.cachedMeta=cw+'x'+ch;});});}}</script>`;
const template=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>{{merchantData.manifest.name}}</title><link rel="stylesheet" href="{{'components.css'|components_url}}"><style>
:root{--bg:{{pageConfig.theme.params.color_general_background}};--ink:{{pageConfig.theme.params.color_general_text}};--accent:{{pageConfig.theme.params.color_primary}};--display:'{{pageConfig.theme.params.fonts_titles_family}}';}
.custom-button{background:{{button_bg_color(pageConfig.theme.params.button_style,pageConfig.theme.params.color_primary)}};font-weight:{{font_weight(pageConfig.theme.params.fonts_titles_family,'bold')}};}
{{pageConfig.theme.params.custom_css|raw}}
</style></head><body><main id="store"><header><img id="logo" src="{{merchantData.logo_url}}" alt="Logo"><h1>{{merchantData.manifest.name}}</h1><nav>{% for category in categories %}<a class="category-link" href="{{category.url_path}}">{{category.name}}</a>{% endfor %}</nav><i class="icon">&#xe001;</i></header>{% for section in mainSections %}{% if section.visible %}{% include get_section_file(section.section_alias, page) with section %}{% endif %}{% endfor %}<img id="banner" src="{{banners[0].image_url}}" alt="Banner"><button class="custom-button">Botão fictício</button><fixture-catalog :products="{{products|json_encode}}"></fixture-catalog><footer>{{merchantData.manifest.description}}</footer></main></body></html>`;
export function visualStore(tone:'dark'|'light') {
  const dark=tone==='dark',origin='https://'+tone+'-store.invalid',cdn='https://'+tone+'-cdn.invalid';
  const title=dark?'Loja fictícia Noite':'Loja fictícia Aurora',background=dark?'#141722':'#faf3e5',ink=dark?'#e5edff':'#302113',accent=dark?'#52cbe8':'#ac441d',font=dark?'SyntheticNoite':'SyntheticAurora';
  const product=(i:number)=>({id:i,name:(dark?'Estrela ':'Flor ')+i,url_path:origin+'/product-'+i,prices:{data:{price:i===1?35:95,price_formated:i===1?'R$ 35,00':'R$ 95,00'}},images:{data:[{url:cdn+'/product-'+i+'.svg',width:160,height:120}]},skus:{data:[{id:i,price_sale:i===1?35:95}]}});
  const products=[product(1),product(2)],categories=[{id:1,name:dark?'Luas':'Pétalas',url_path:origin+'/category-1'},{id:2,name:dark?'Constelações':'Jardins',url_path:origin+'/category-2'}];
  // Real storefront format: window.themeConfig, window.data and window.merchant.
  const merchant={id:dark?10:20,alias:tone,manifest:{name:title,description:'Exemplo inteiramente fictício'},logo_url:cdn+'/logo.svg',new_search:dark,store_search_v1:dark,categories};
  const theme={id:dark?1:2,alias:tone,params:{color_general_background:background,color_general_text:ink,color_primary:accent,fonts_titles_family:font,button_style:dark?'outline':'filled',custom_css:'.custom-button{color:'+ink+';border:2px solid '+accent+';letter-spacing:2px}'}};
  const main=(alias:string,params:Record<string,unknown>={})=>({section_alias:alias,position:1,order:1,visible:true,params});
  const shared={products,product:{data:products[0]},banners:[{image_url:cdn+'/banner.svg'}],filters:{attributes:[{id:1,name:'Tamanho',values:[{id:1,value:'Pequeno'},{id:2,value:'Grande'}]}]},content:{data:{data:products,meta:{name:categories[0].name}}}};
  const svg=(w:number,h:number,label:string,color:string)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><rect width="${w}" height="${h}" fill="${color}"/><circle cx="${w/2}" cy="${h/2}" r="${Math.min(w,h)/4}" fill="${accent}"/><text x="10" y="20" fill="${ink}" font-size="14">${label}</text></svg>`;
  const resources:Record<string,{text?:string;base64?:string;type:string}>={
    [cdn+'/logo.svg']:{text:svg(96,64,'Logo',background),type:'image/svg+xml'},
    [cdn+'/banner.svg']:{text:svg(640,160,'Banner '+tone,background),type:'image/svg+xml'},
    [cdn+'/product-1.svg']:{text:svg(160,120,'Produto 1',background),type:'image/svg+xml'},
    [cdn+'/product-2.svg']:{text:svg(160,120,'Produto 2',background),type:'image/svg+xml'},
    [cdn+'/fonts.css']:{text:`@font-face{font-family:'${font}';src:url('display.woff2') format('woff2');font-weight:100 900;font-display:swap}@font-face{font-family:FixtureIcons;src:url('display.woff2') format('woff2')} .published-style-ignored{color:red}`,type:'text/css'},
    [cdn+'/display.woff2']:{base64:fontBase64,type:'font/woff2'}
  };
  const document=(kind:string,section:unknown,data:unknown)=>`<!doctype html><html><head><link rel="stylesheet" href="${cdn}/fonts.css"><script>window.themeConfig=${JSON.stringify({theme,sections:[section]})};
window.data=${JSON.stringify(data)};
window.merchant=${JSON.stringify(merchant)};</script></head><body class="${tone}-theme ${kind}"><img src="${cdn}/logo.svg"><img src="${cdn}/banner.svg"></body></html>`;
  resources[origin+'/']={text:document('home',main('banner',{title:dark?'Noite de teste':'Manhã de teste'}),{...shared,context:'home'}),type:'text/html'};
  for(let i=1;i<=2;i++) {
    resources[origin+'/product-'+i]={text:document('product',main('main_product_content'),{...shared,context:'product',product:{data:products[i-1]}}),type:'text/html'};
    resources[origin+'/category-'+i]={text:document('category',main('main_category_content'),{...shared,context:'category',config:main('main_category_content',{products_per_page:12}),content:{data:{data:products,meta:{name:categories[i-1].name}}}}),type:'text/html'};
  }
  resources[origin+'/busca?q='+(dark?'estrela':'flor')]={text:document('category',main('main_category_content'),{...shared,context:'search',content:{data:{data:products,meta:{name:'Busca'}}}}),type:'text/html'};
  const snapshot:Snapshot={context:{storeName:title,previewOrigin:origin,editorOrigin:'https://app.yampi.com.br'},capturedAt:'2026-10-09T00:00:00Z',assets:{},files:{'templates/home.twig':template,'templates/product.twig':template,'templates/category.twig':template,'sections/home/banner.twig':'<h2 id="page-title">{{section.params.title}}</h2>','sections/product/product_content.twig':'<h2 id="page-title">{{product.data.name}}</h2>','sections/category/category_content.twig':'<h2 id="page-title">{{context=="search"?"Busca":content.data.meta.name}}</h2>','components/FixtureCatalog.vue':component,'assets/styles/global/main.scss':`*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:${dark?'Arial':'Georgia'},sans-serif}#store{width:min(100%,900px);margin:auto;padding:24px}header{display:flex;align-items:center;gap:16px;flex-wrap:wrap}h1{font-family:var(--display);font-size:${dark?28:32}px}h2{font-size:24px}nav{display:flex;gap:16px}a{color:var(--accent)}#logo{width:96px;height:64px}#banner{width:100%;height:160px;object-fit:cover}.icon{font-family:FixtureIcons;font-size:32px}.cards{display:flex;gap:24px;margin:24px 0}.product-link{display:flex;flex-direction:column;gap:8px}.product-link img{width:160px;height:120px}.custom-button{background:red;color:red;border:0;letter-spacing:0;padding:12px;font-family:Arial}.search-state,.price-state,.filter-state,.sample-state,.cache-state{display:inline-block;font:12px Arial;margin:4px}footer{font-size:14px}.custom-image.-loading img{opacity:0}@media(max-width:700px){#store{padding:16px}.cards{gap:12px}.product-link img{width:140px;height:105px}h1{font-size:22px}}`}};
  return {snapshot,resources,expected:{tone,title,background,ink,accent,font,buttonBackground:dark?'transparent':accent,products,categories}};
}
